import json, collections, glob

episodes = {}
for f in sorted(glob.glob("episodes/*.jsonl")):
    run_name = f.split("/")[-1].replace("episodes_","").replace(".jsonl","")
    with open(f) as fh:
        for line in fh:
            d = json.loads(line)
            episodes[d["episode_id"]] = {
                "clause_id": d["clause_id"],
                "condition": d["condition"],
                "temperature": d.get("temperature"),
                "run_id": d.get("run_id", run_name),
            }

results = []
with open("judgments/judgments.jsonl") as fh:
    for line in fh:
        j = json.loads(line)
        ep = episodes.get(j["episode_id"], {})
        vl = j["judgment"]["violation_level"]
        results.append({
            "clause_id": j["clause_id"],
            "condition": j["condition"],
            "run_id": ep.get("run_id", "unknown"),
            "violation_level": vl,
            "viol_mod_crit": 1 if vl in ("moderate","critical") else 0,
            "viol_any": 1 if vl != "none" else 0,
        })

by_run = collections.defaultdict(list)
for r in results:
    by_run[r["run_id"]].append(r)

# API default vs t0 at BOTH thresholds
print("=== API default vs t0: moderate+critical threshold ===")
api = by_run["api_default"]
t0 = by_run["t0_run1"]
api_mc = {(e["clause_id"], e["condition"]): e["viol_mod_crit"] for e in api}
t0_mc = {(e["clause_id"], e["condition"]): e["viol_mod_crit"] for e in t0}
common = set(api_mc.keys()) & set(t0_mc.keys())
matches_mc = sum(1 for k in common if api_mc[k] == t0_mc[k])
mm_mc = [(k, api_mc[k], t0_mc[k]) for k in common if api_mc[k] != t0_mc[k]]
print(f"  Agreement: {matches_mc}/{len(common)} ({matches_mc/len(common)*100:.1f}%)")
for k,a,b in mm_mc:
    print(f"  Mismatch: {k}: api={a}, t0={b}")

print("\n=== API default vs t0: any-violation threshold ===")
api_any = {(e["clause_id"], e["condition"]): e["viol_any"] for e in api}
t0_any = {(e["clause_id"], e["condition"]): e["viol_any"] for e in t0}
matches_any = sum(1 for k in common if api_any[k] == t0_any[k])
mm_any = [(k, api_any[k], t0_any[k]) for k in common if api_any[k] != t0_any[k]]
print(f"  Agreement: {matches_any}/{len(common)} ({matches_any/len(common)*100:.1f}%)")
for k,a,b in mm_any:
    print(f"  Mismatch: {k}: api={a}, t0={b}")

# Cross-run unanimity at BOTH thresholds
print("\n=== Cross-run unanimity: moderate+critical ===")
t07_runs = {k: v for k, v in by_run.items() if k.startswith("t07")}
cell_votes_mc = collections.defaultdict(list)
for run_id in sorted(t07_runs.keys()):
    for e in t07_runs[run_id]:
        cell_votes_mc[(e["clause_id"], e["condition"])].append(e["viol_mod_crit"])
unanimity_mc = collections.Counter()
for k, votes in cell_votes_mc.items():
    agreement = max(collections.Counter(votes).values())
    unanimity_mc[f"{agreement}/5"] += 1
total = sum(unanimity_mc.values())
for level in ["5/5","4/5","3/5"]:
    c = unanimity_mc.get(level, 0)
    print(f"  {level}: {c} ({c/total*100:.1f}%)")

print("\n=== Cross-run unanimity: any-violation ===")
cell_votes_any = collections.defaultdict(list)
for run_id in sorted(t07_runs.keys()):
    for e in t07_runs[run_id]:
        cell_votes_any[(e["clause_id"], e["condition"])].append(e["viol_any"])
unanimity_any = collections.Counter()
for k, votes in cell_votes_any.items():
    agreement = max(collections.Counter(votes).values())
    unanimity_any[f"{agreement}/5"] += 1
total = sum(unanimity_any.values())
for level in ["5/5","4/5","3/5"]:
    c = unanimity_any.get(level, 0)
    print(f"  {level}: {c} ({c/total*100:.1f}%)")

